from dataclasses import dataclass
from decimal import Decimal
from enum import Enum
from datetime import date
from typing import Union

ZERO_CENTS = 0
MAX_SETTLEMENT_MEMBERS = 12

class SplitKind(Enum):
    EQUAL = "equal"
    AMOUNTS = "amounts"
    PERCENTAGES = "percentages"
    SHARES = "shares"

@dataclass(frozen=True)
class Member:
    member_id: str
    name: str

@dataclass(frozen=True)
class ExchangeRate:
    currency: str
    base_per_unit: Decimal

@dataclass(frozen=True)
class SplitEntry:
    member_id: str
    value: Decimal

@dataclass(frozen=True)
class Expense:
    expense_id: str
    payer_id: str
    amount: Decimal
    currency: str
    split_kind: SplitKind
    entries: tuple[SplitEntry, ...]
    description: str
    occurred_on: date

@dataclass(frozen=True)
class Payment:
    payment_id: str
    from_member_id: str
    to_member_id: str
    amount_cents: int
    note: str
    occurred_on: date

@dataclass(frozen=True)
class ExpenseAction:
    expense: Expense

@dataclass(frozen=True)
class PaymentAction:
    payment: Payment

Action = Union[ExpenseAction, PaymentAction]

@dataclass(frozen=True)
class Trip:
    trip_id: str
    name: str
    base_currency: str
    members: tuple[Member, ...]
    rates: tuple[ExchangeRate, ...]
    actions: tuple[Action, ...]
    closed: bool

@dataclass(frozen=True)
class Allocation:
    member_id: str
    cents: int

@dataclass(frozen=True)
class Transfer:
    from_member_id: str
    to_member_id: str
    cents: int

@dataclass(frozen=True)
class StatementLine:
    action_id: str
    kind: str
    description: str
    paid_cents: int
    owed_cents: int
    sent_cents: int
    received_cents: int

@dataclass(frozen=True)
class Statement:
    member_id: str
    paid_cents: int
    owed_cents: int
    sent_cents: int
    received_cents: int
    balance_cents: int
    lines: tuple[StatementLine, ...]

class DomainError(Exception):
    pass

class ValidationError(DomainError):
    pass

class ClosedTripError(DomainError):
    pass

class EmptyHistoryError(DomainError):
    pass

class TripNotFoundError(DomainError):
    pass

