from app.domain import Trip, TripNotFoundError
from app.abilities import TripRepository

class InMemoryTripRepository(TripRepository):
    def __init__(self, trips: tuple[Trip, ...] = ()) -> None:
        self.trips = {trip.trip_id: trip for trip in trips}

    def load_trip(self, trip_id: str) -> Trip:
        if trip_id not in self.trips:
            raise TripNotFoundError(trip_id)
        return self.trips[trip_id]

    def save_trip(self, trip: Trip) -> None:
        self.trips[trip.trip_id] = trip
